  "about_items": [
    {
      "n": "#3·15",
      "text": "This sleeveless top is made of a soft peach fabric with a structured collar and a gold button at the neck. Its clean lines sit perfectly on your narrow shoulders while flowing gently over your hips."
    },
    {
      "n": "#47·33",
      "text": "These white plaid shorts have a high waist and a bold check pattern that sets off your wider hips. Their crisp silhouette balances the softness of the top while keeping your look neat for work."
    },
    {
      "n": "#285·21",
      "text": "The brown crossbody bag is made of suede with two buckled handles and a rounded shape that feels both casual and polished. Its deep tone grounds your outfit against the light pinks and white of the other pieces."
    },
    {
      "n": "#269·15",
      "text": "This red headband is made of smooth satin with a wide band that wraps comfortably around your hair. Its vivid hue adds a playful accent to your look without overpowering the softer tones of your top and shorts."
    },
    {
      "n": "#18·09",
      "text": "The chocolate ankle boots are crafted from soft suede with a chunky lug sole and round toe. Their warm brown color matches the bag and adds stability for walking around your office or outside in the autumn air."
    },
    {
      "n": "#466·38",
      "text": "This pink belt is made of soft velvet with a long tie that wraps neatly around your waist. Its gentle hue echoes the top and adds a touch of femininity while keeping your silhouette balanced over the shorts."
    }
  ]
